import logging
import time
import gpiozero
import picamera2
import adafruit_circuitpython_ads1x15
import paho.mqtt.client as mqtt

class ADS1015:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.i2c = gpiozero.I2C(busnum=busnum)
        self.ads = adafruit_circuitpython_ads1x15.ADS1015(self.i2c, address=self.address)
        self.logger = logging.getLogger(__name__)

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        try:
            self.ads.start_single_ended_conversion(channel, pga, sps)
            time.sleep(0.001)
            result = self.ads.get_last_conversion_results()
            return result
        except Exception as e:
            self.logger.error(e)
            return None

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        try:
            self.ads.start_continuous_conversion(channel, pga, sps)
        except Exception as e:
            self.logger.error(e)

    def get_last_conversion_results(self):
        try:
            result = self.ads.get_last_conversion_results()
            return result
        except Exception as e:
            self.logger.error(e)
            return None

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        try:
            self.ads.start_single_ended_comparator(channel, threshold_high, threshold_low, pga, sps, active_low, traditional_mode, latching, num_readings)
        except Exception as e:
            self.logger.error(e)

    def __del__(self):
        self.i2c.close()

def main():
    ads = ADS1015()
    ads.read_adc_single_ended(channel=0, pga=6144, sps=250)
    ads.start_continuous_conversion(channel=0, pga=6144, sps=250)
    ads.get_last_conversion_results()
    ads.start_single_ended_comparator(channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1)

if __name__ == "__main__":
    main()

