import time
import spidev
import RPi.GPIO as GPIO
import paho.mqtt.client as mqtt

class SmartGardenController:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 1350000
        self.spi.mode = 0
        self.spi.bits_per_word = 10
        self.spi.cshigh = False
        self.spi.loop = False

        self.gpio = GPIO.setup(18, GPIO.OUT)

        self.mqtt_client = mqtt.Client()
        self.mqtt_client.connect("localhost")

    def read_moisture(self):
        try:
            raw_value = self.spi.xfer2([1, 8, 0])
            return raw_value[2]
        except spidev.SpiDevError as e:
            print(f"SPI error: {e}")
            return None

    def run_pump(self, seconds):
        GPIO.output(self.gpio, GPIO.HIGH)
        time.sleep(seconds)
        GPIO.output(self.gpio, GPIO.LOW)

    def irrigation_cycle(self):
        raw_value = self.read_moisture()
        if raw_value is not None and raw_value < 450:
            self.run_pump(2)
            return True
        else:
            return False

    def close(self):
        self.spi.close()
        GPIO.cleanup()
        self.mqtt_client.disconnect()

def schedule_cycles(controller, cycle_count, interval_seconds):
    for i in range(cycle_count):
        if controller.irrigation_cycle():
            controller.mqtt_client.publish("irrigation/status", "ON")
        else:
            controller.mqtt_client.publish("irrigation/status", "OFF")
        time.sleep(interval_seconds)

if __name__ == "__main__":
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        controller.close()

