    try:
        read_distance()
    except KeyboardInterrupt:
        logging.info('Interrupted')
    finally:
        ser.close()

if __name__ == '__main__':
    main()

import logging
import time
import smbus
import struct

class DHT20:
    def __init__(self, bus_num=1):
        self.bus = smbus.SMBus(bus_num)
        self.addr = 0x20
        self.status_reg = 0x00
        self.data_reg = 0x01
        self.crc_poly = 0x31
        self.crc_init = 0xFF
        self.timeout = 0.1

        try:
            self.bus.open()
            self.bus.write_byte(self.addr, self.status_reg)
            status = self.bus.read_byte(self.addr)
            if status != 0x00:
                raise ValueError("Invalid status register value: {}".format(status))
        except Exception as e:
            logging.error("Error opening I2C bus: {}".format(e))
            self.bus = None

    def measure(self):
        if self.bus is None:
            return (None, None, True)

        try:
            self.bus.write_byte(self.addr, self.data_reg)
            data = self.bus.read_i2c_block_data(self.addr, self.data_reg, 6)
            humidity = struct.unpack("<H", data[0:2])[0]
            temperature = struct.unpack("<h", data[2:4])[0]
            crc = struct.unpack("<B", data[4:5])[0]
            crc_check = self.crc8(data[0:6], self.crc_poly, self.crc_init)
            if crc != crc_check:
                raise ValueError("CRC mismatch: expected {}, got {}".format(crc_check, crc))
            return (temperature, humidity, False)
        except Exception as e:
            logging.error("Error reading data: {}".format(e))
            return (None, None, True)

    def crc8(self, data, poly, init):
        crc = init
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ poly
                else:
                    crc <<= 1
        return crc & 0xFF

if __name__ == "__main__":
    dht20 = DHT20()
    temperature, humidity, crc_error = dht20.measure()
    if crc_error:
        print("Error reading data")
    else:
        print("Temperature: {}°C".format(temperature))
        print("Humidity: {}%".format(humidity))

