import logging
import time
import gpiozero
import picamera2
import adafruit_circuitpython_dht
import paho.mqtt.client as mqtt

class DHT20Driver:
    def __init__(self, i2c_bus):
        self.i2c_bus = i2c_bus
        self.dht20 = adafruit_circuitpython_dht.DHT20(i2c_bus)
        self.logger = logging.getLogger(__name__)

    def begin(self):
        try:
            self.dht20.power_on()
            time.sleep(0.5)
            self.dht20.wait_for_status()
            self.logger.info("DHT20 driver initialized")
        except OSError as e:
            self.logger.error("Failed to initialize DHT20 driver: %s", e)
            return False
        return True

    def get_temperature_and_humidity(self):
        if time.time() - self.last_read_time < 2:
            return self.last_temperature, self.last_humidity, False

        for i in range(5):
            try:
                data = self.dht20.read_data()
                if data[6] != adafruit_circuitpython_dht.crc8(data[:6]):
                    self.logger.warning("CRC mismatch in DHT20 data")
                    continue
                self.last_temperature = data[0] / 100
                self.last_humidity = data[1] / 100
                self.last_read_time = time.time()
                return self.last_temperature, self.last_humidity, False
            except OSError as e:
                self.logger.error("Failed to read DHT20 data: %s", e)
                time.sleep(0.01)
        return None, None, True

    def close(self):
        self.dht20.power_off()
        self.i2c_bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    i2c_bus = gpiozero.I2C(1)
    dht20 = DHT20Driver(i2c_bus)
    if not dht20.begin():
        print("Failed to initialize DHT20 driver")
        exit(1)

    try:
        while True:
            temperature, humidity, error = dht20.get_temperature_and_humidity()
            if error:
                print("Failed to read DHT20 data")
                continue
            print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting...")
        dht20.close()
        exit(0)

