import RPi.GPIO as GPIO
import time
import signal

class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.counter = 0
        self.state = 0

        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(self.dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        GPIO.add_event_detect(self.clk_pin, GPIO.BOTH, callback=self.clk_callback)
        GPIO.add_event_detect(self.dt_pin, GPIO.BOTH, callback=self.dt_callback)

    def clk_callback(self, channel):
        if GPIO.input(self.clk_pin):
            self.state = (self.state + 1) % 4
        else:
            self.state = (self.state - 1) % 4

        if self.state == 0:
            self.counter += 1
        elif self.state == 2:
            self.counter -= 1

        if self.callback:
            self.callback(self.counter)

    def dt_callback(self, channel):
        if GPIO.input(self.dt_pin):
            self.state = (self.state + 2) % 4
        else:
            self.state = (self.state - 2) % 4

        if self.state == 0:
            self.counter += 1
        elif self.state == 2:
            self.counter -= 1

        if self.callback:
            self.callback(self.counter)

    def cleanup(self):
        GPIO.remove_event_detect(self.clk_pin)
        GPIO.remove_event_detect(self.dt_pin)
        GPIO.cleanup()

def main():
    encoder = RotaryEncoder(17, 18, callback=lambda x: print(x))

    signal.signal(signal.SIGINT, encoder.cleanup)
    signal.signal(signal.SIGTERM, encoder.cleanup)

    try:
        while True:
            time.sleep(0.1)
    except KeyboardInterrupt:
        encoder.cleanup()

if __name__ == "__main__":
