        self.prev_clk_state = None
        self.prev_dt_state = None

        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(self.dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        if self.callback and not callable(self.callback):
            raise ValueError("Callback must be callable")

        GPIO.add_event_detect(self.clk_pin, GPIO.BOTH, callback=self._clk_callback)
        GPIO.add_event_detect(self.dt_pin, GPIO.BOTH, callback=self._dt_callback)

    def _clk_callback(self, channel):
        clk_state = GPIO.input(self.clk_pin)
        if self.prev_clk_state is None:
            self.prev_clk_state = clk_state
            return

        if clk_state != self.prev_clk_state:
            dt_state = GPIO.input(self.dt_pin)
            if dt_state != self.prev_dt_state:
                if clk_state == GPIO.HIGH:
                    self.counter += 1
                else:
                    self.counter -= 1

                if self.callback:
                    try:
                        self.callback(self.counter)
                    except Exception as e:
                        print(f"Error in callback: {e}")

                self.prev_dt_state = dt_state

        self.prev_clk_state = clk_state

    def _dt_callback(self, channel):
        dt_state = GPIO.input(self.dt_pin)
        if self.prev_dt_state is None:
            self.prev_dt_state = dt_state
            return

        if dt_state != self.prev_dt_state:
            clk_state = GPIO.input(self.clk_pin)
            if clk_state != self.prev_clk_state:
                if dt_state == GPIO.HIGH:
                    self.counter += 1
                else:
                    self.counter -= 1

                if self.callback:
                    try:
                        self.callback(self.counter)
                    except Exception as e:
                        print(f"Error in callback: {e}")

                self.prev_clk_state = clk_state

        self.prev_dt_state = dt_state

    def cleanup(self):
        GPIO.cleanup()

if __name__ == "__main__":
    try:
        encoder = RotaryEncoder(17, 18, callback=lambda x: print(f"Counter: {x}"))
        while True:
            time.sleep(0.005)
    except KeyboardInterrupt:
        encoder.cleanup()
