import RPi.GPIO as GPIO
import time

GPIO.setmode(GPIO.BCM)
GPIO.setup(17, GPIO.OUT)

def turn_on_led(pin):
    GPIO.output(pin, GPIO.HIGH)

def turn_off_led(pin):
    GPIO.output(pin, GPIO.LOW)

def main():
    print("Starting LED blink program")
    try:
        while True:
            turn_on_led(17)
            time.sleep(1)
            turn_off_led(17)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting LED blink program")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

import time
import gpiozero
import picamera2
import adafruit_circuitpython_gpio
import paho.mqtt.client as mqtt

class LEDController:
    def __init__(self, pin):
        self.pin = pin
        self.led = gpiozero.LED(self.pin)
        self.led.off()

        self.client = mqtt.Client()
        self.client.connect("localhost")

        self.client.on_connect = self.on_connect
        self.client.on_message = self.on_message

        self.client.loop_start()

    def on_connect(self, client, userdata, flags, rc):
        print("Connected to MQTT broker")

    def on_message(self, client, userdata, msg):
        print(f"Received message: {msg.payload.decode()}")

    def on(self):
        self.led.on()

    def off(self):
        self.led.off()

    def blink(self, on_duration, off_duration):
        if on_duration < 0 or off_duration < 0:
            raise ValueError("Invalid duration")

        self.on()
        time.sleep(on_duration)
        self.off()
        time.sleep(off_duration)

def main():
    try:
        led = LEDController(25)

        while True:
            led.blink(1.0, 0.5)

    except ValueError as e:
        print(f"Error: {e}")

    finally:
        led.off()
        led.client.disconnect()
        led.client.loop_stop()

if __name__ == "__main__":
    main()

