from gpiozero import AngularServo
from picamera2 import PiCamera2
from adafruit_circuitpython_pca9685 import PCA9685
from paho.mqtt.client import Client

class RoboticArm:
    def __init__(self, base_pin, shoulder_pin, gripper_pin):
        self.base = AngularServo(base_pin, frequency=50, min_pulse_width=0.5, max_pulse_width=2.5)
        self.shoulder = AngularServo(shoulder_pin, frequency=50, min_pulse_width=0.5, max_pulse_width=2.5)
        self.gripper = AngularServo(gripper_pin, frequency=50, min_pulse_width=0.5, max_pulse_width=2.5)

    def move_joint(self, joint, target_angle):
        try:
            joint.angle = target_angle
            sleep(0.4)
        except gpiozero.exc.OutputDeviceBadValue:
            print("Invalid angle:", target_angle)

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        self.move_joint(self.base, base_angle)
        self.move_joint(self.shoulder, shoulder_angle)
        self.move_joint(self.gripper, gripper_angle)
        print("Pose:", base_angle, shoulder_angle, gripper_angle)

    def run_demo_sequence(self):
        self.go_to_pose(0, 0, 0)
        self.go_to_pose(45, -30, 20)
        self.go_to_pose(-45, 30, -20)
        self.go_to_pose(0, 0, 0)

