import logging
import time
import gpiozero
import picamera2
import adafruit_circuitpython_automationhat
import paho.mqtt.client as mqtt

class GarageDoor:
    def __init__(self):
        self.state_pin = 1
        self.relay = adafruit_circuitpython_automationhat.Relay.one
        self.reed_switch = gpiozero.Button(self.state_pin)
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.connect("localhost")
        self.mqtt_client.loop_start()

    def read_state(self):
        try:
            state = self.reed_switch.is_active
            logging.info(f"Garage door state: {state}")
            return state
        except gpiozero.Button.ButtonError as e:
            logging.error(f"Error reading reed switch: {e}")
            return None

    def open_door(self):
        try:
            self.relay.on()
            time.sleep(0.5)
            self.relay.off()
            logging.info("Garage door opened")
        except adafruit_circuitpython_automationhat.RelayError as e:
            logging.error(f"Error opening garage door: {e}")

    def close_door(self):
        try:
            self.relay.on()
            time.sleep(0.5)
            self.relay.off()
            logging.info("Garage door closed")
        except adafruit_circuitpython_automationhat.RelayError as e:
            logging.error(f"Error closing garage door: {e}")

    def run(self):
        while True:
            state = self.read_state()
            if state is None:
                continue
            if state:
                self.open_door()
            else:
                self.close_door()

