class I2CDevice:
    def __init__(self, address, bus_number=1):
        self.address = address
        self.bus_number = bus_number
        self.i2c = adafruit_circuitpython_i2c.I2C(scl=gpiozero.Pin(2), sda=gpiozero.Pin(3))
        self.i2c.probe(self.address)
        if not self.i2c.is_connected(self.address):
            raise RuntimeError("I2C device not found at address {}".format(self.address))

    def write_byte(self, register, value):
        self.i2c.write_byte(self.address, register, value)

    def read_byte(self, register):
        return self.i2c.read_byte(self.address, register)

    def close(self):
        self.i2c.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

if __name__ == "__main__":
    i2c = I2CDevice(0x12, 1)
    with i2c:
        i2c.write_byte(0x00, 0x01)
        print(i2c.read_byte(0x00))

