import time
import datetime
import smbus
import struct

class DS1338RTC:
    def __init__(self, bus=1):
        self.bus = smbus.SMBus(bus)
        self.addr = 0x68
        self.open()

    def open(self):
        try:
            self.bus.open(self.addr)
        except IOError as e:
            raise IOError(f"Failed to open I2C bus {self.bus} at address {self.addr}: {e}")

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def read_all(self):
        try:
            data = self.bus.read_i2c_block_data(self.addr, 0, 7)
        except IOError as e:
            raise IOError(f"Failed to read from I2C bus {self.bus} at address {self.addr}: {e}")

        year = data[0]
        month = data[1]
        date = data[2]
        day = data[3]
        hours = data[4]
        minutes = data[5]
        seconds = data[6]

        return (year, month, date, day, hours, minutes, seconds)

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime.datetime(year, month, date, day, hours, minutes, seconds, tzinfo=datetime.timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (0 <= year <= 99):
            raise ValueError(f"Year must be between 0 and 99, got {year}")
        if not (1 <= month <= 12):
            raise ValueError(f"Month must be between 1 and 12, got {month}")
        if not (1 <= date <= 31):
            raise ValueError(f"Date must be between 1 and 31, got {date}")
        if not (1 <= day <= 7):
            raise ValueError(f"Day must be between 1 and 7, got {day}")
        if not (0 <= hours <= 23):
            raise ValueError(f"Hours must be between 0 and 23, got {hours}")
        if not (0 <= minutes <= 59):
            raise ValueError(f"Minutes must be between 0 and 59, got {minutes}")
        if not (0 <= seconds <= 59):
            raise ValueError(f"Seconds must be between 0 and 59, got {seconds}")

        data = struct.pack(">BBBBBBB", year, month, date, day, hours, minutes, seconds)
        try:
            self.bus.write_i2c_block_data(self.addr, 0, data)
        except IOError as e:
            raise IOError(f"Failed to write to I2C bus {self.bus} at address {self.addr}: {e}")

    def write_datetime(self, dt):
        year = dt.year - 2000
        month = dt.month
        date = dt.day
        day = dt.isoweekday()
        hours = dt.hour
        minutes = dt.minute
        seconds = dt.second
        self.write_all(year, month, date, day, hours, minutes, seconds)

    def write_now(self):
        self.write_datetime(datetime.datetime.now(datetime.timezone.utc))

if __name__ == "__main__":
    try:
        rtc = DS1338RTC()
        print(rtc.read_datetime())
    except IOError as e:
        print(f"Failed to read from DS1338 RTC: {e}", file=sys.stderr)
        sys.exit(0)

