import serial
import time
import re
import paho.mqtt.client as mqtt

class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.ser = None
        self.connect()

    def connect(self):
        try:
            self.ser = serial.Serial(self.port, self.baud_rate, timeout=self.timeout)
        except serial.SerialException:
            print("Failed to open serial port")
            return

        if not self.test_connection():
            print("Failed to connect to ESP8266")
            self.ser.close()
            return

        print("Connected to ESP8266")

    def test_connection(self):
        self._send_command('AT', 'OK')

    def restart(self):
        self._send_command('AT+RST', 'ready')
        time.sleep(2)
        self.connect()

    def connect_wifi(self, ssid, password):
        self._send_command('AT+CWJAP', ssid, password, timeout=10)

    def disconnect_wifi(self):
        self._send_command('AT+CWQAP')

    def get_ip(self):
        response = self._send_command('AT+CIFSR')
        if response:
            return re.search(r'STAIP,(\d+\.\d+\.\d+\.\d+)', response).group(1)
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        self._send_command('AT+CIPSTART', 'CONN', host, port)
        self._send_command('AT+CIPSEND', method, url, headers, data)
        response = self._send_command('AT+CIPSEND', 'OK')
        if response:
            return response.decode('utf-8')
        return None

    def receive_http_response(self, timeout=5.0):
        response = self._send_command('AT+CIPSEND', 'OK')
        if response:
            return response.decode('utf-8')
        return None

    def _send_command(self, command, terminator, timeout=1.0):
        if not self.ser:
            return None

        self.ser.write(command.encode('utf-8'))
        response = self.ser.read_until(terminator.encode('utf-8'), timeout)
        if response:
            return response.decode('utf-8')
        return None

    def __del__(self):
        if self.ser:
            self.ser.close()

if __name__ == '__main__':
    esp = ESP8266()
    if not esp.connect():
        print("Failed to connect to ESP8266")
        exit(1)

    esp.restart()
    esp.connect_wifi('my_ssid', 'my_password')
    ip = esp.get_ip()
    print(f"IP address: {ip}")

    response = esp.send_http_request('GET', 'http://www.example.com', 'www.example.com')
    print(response)

    response = esp.receive_http_response()
    print(response)

    esp.disconnect_wifi()
    esp.ser.close()

