# Open the GPS module over UART using /dev/serial0 at 9600 baud
ser = serial.Serial('/dev/serial0', 9600)

# Read NMEA data with a 1 second read timeout
while True:
    try:
        data = ser.readline(timeout=1)
        if data:
            # Parse $GPRMC sentences to extract latitude and longitude
            msg = pynmea2.parse(data)
            if msg.sentence_type == 'GPRMC':
                if msg.status == 'A':
                    # Convert raw ddmm.mmmm coordinates to decimal-degree values
                    lat = msg.latitude.split('.')[0] + '.' + msg.latitude.split('.')[1][:2]
                    lon = msg.longitude.split('.')[0] + '.' + msg.longitude.split('.')[1][:2]
                    print(f'Latitude: {lat}, Longitude: {lon}')
                    time.sleep(1)
                else:
                    print('Invalid status field')
            else:
                print('Invalid sentence type')
        else:
            print('No data received')
    except serial.SerialException:
        print('Port open failure')
    except pynmea2.ParseError:
        print('Parse error')
    except KeyboardInterrupt:
        print('User abort')
    finally:
        ser.close()

