import serial
import time

class ESP8266:
    def __init__(self, port, baudrate=115200):
        self.port = serial.Serial(port, baudrate, timeout=5)
        self.port.flushInput()
        self.port.flushOutput()

    def _send_command(self, command, delay=1, max_retries=3):
        self.port.write(command.encode())
        time.sleep(delay)
        response = self.port.readline()
        if response:
            return response.decode().strip()
        else:
            return None

    def test_connection(self):
        response = self._send_command("AT\r\n")
        if response == "OK":
            return True
        else:
            return False

    def restart(self):
        response = self._send_command("AT+RST\r\n")
        time.sleep(2)
        if response == "OK":
            return True
        else:
            return False

    def connect_wifi(self, ssid, password):
        response = self._send_command("AT+CWJAP_CUR=\"{}\",\"{}\"\r\n".format(ssid, password))
        time.sleep(5)
        if "WIFI GOT IP" in response:
            return True
        else:
            return False

    def __del__(self):
        self.port.close()

if __name__ == "__main__":
    esp = ESP8266("/dev/ttyUSB0")
    if esp.test_connection():
        print("ESP8266 connected")
    else:
        print("ESP8266 not connected")
    if esp.restart():
        print("ESP8266 restarted")
    else:
        print("ESP8266 not restarted")
    if esp.connect_wifi("my_ssid", "my_password"):
        print("WiFi connected")
    else:
        print("WiFi not connected")
    esp.port.close()

