import serial
import time

class GPSModule:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        try:
            self.port = serial.Serial(port, baud, timeout=1)
        except serial.SerialException as e:
            raise ValueError(f'Failed to open port {port}: {e}')

    def attach(self):
        try:
            self.port.write(b'AT+CGNSPWR=1\r\n')
            time.sleep(1)
            if self.port.readline().startswith(b'$GPRMC'):
                return self.port.readline().split(b',')
            else:
                return None
        except serial.SerialException as e:
            raise ValueError(f'Failed to write to port {self.port}: {e}')

    def detach(self):
        try:
            self.port.write(b'AT+CGNSPWR=0\r\n')
            time.sleep(1)
            if self.port.readline().startswith(b'$GPRMC'):
                return self.port.readline().split(b',')
            else:
                return None
        except serial.SerialException as e:
            raise ValueError(f'Failed to write to port {self.port}: {e}')

    def get_data(self):
        try:
            data = self.port.readline()
            if data.startswith(b'$GPRMC'):
                return data.split(b',')
            else:
                return None
        except serial.SerialException as e:
            raise ValueError(f'Failed to read from port {self.port}: {e}')

    def close(self):
        self.port.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

if __name__ == '__main__':
    gps = GPSModule()
    with gps:
        print(gps.get_data())

