import logging
import serial
import time

class SimpleGPS:
    def __init__(self, port="/dev/serial0", baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None

    def connect(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            return True
        except OSError:
            logging.error("Failed to open serial port")
            return False

    def read_data(self):
        try:
            data = self.ser.readline().decode("utf-8").strip()
            return data
        except serial.SerialException:
            logging.error("Failed to read from serial port")
            return None

    def parse_gga(self, line):
        try:
            if line.startswith("$GPGGA") or line.startswith("$GNGGA"):
                fields = line.split(",")
                utc_time = fields[1]
                latitude = fields[2]
                longitude = fields[3]
                fix_quality = fields[4]
                num_satellites = fields[5]
                return {
                    "utc_time": utc_time,
                    "latitude": latitude,
                    "longitude": longitude,
                    "fix_quality": fix_quality,
                    "num_satellites": num_satellites
                }
            else:
                return None
        except IndexError:
            logging.error("Malformed GGA sentence")
            return None
        except ValueError:
            logging.error("Malformed GGA sentence")
            return None

    def close(self):
        if self.ser is not None:
            self.ser.close()
            self.ser = None

if __name__ == "__main__":
    gps = SimpleGPS()
    if gps.connect():
        logging.info("Connected to GPS module")
        while True:
            data = gps.read_data()
            if data is not None:
                parsed_data = gps.parse_gga(data)
                if parsed_data is not None:
                    logging.info(parsed_data)
            time.sleep(1)
    else:
        logging.error("Failed to connect to GPS module")
    gps.close()

