import gpiozero
import picamera2
import adafruit_circuitpython_scpi
import paho.mqtt.client as mqtt

# Set up the serial connection to the SCPI instrument
ser = serial.Serial('/dev/ttyUSB0', 9600, 8, 1, timeout=0.1)

# Set up the MQTT client
client = mqtt.Client()
client.connect('localhost')

# Set up the web service
app = Flask(__name__)

# Define the routes
@app.route('/version')
def version():
    # Send the SCPI identification query
    ser.write('*IDN?\n'.encode())
    # Wait for the response
    time.sleep(0.1)
    # Read the response
    response = ser.read_all()
    # Return the response as text/html
    return Response(response.decode(), mimetype='text/html')

@app.route('/getdata')
def get_data():
    # Return the full list as JSON
    return jsonify(list)

@app.route('/getset/<int:item_id>')
def get_set(item_id):
    # Return the matching item as JSON or a 404 if not found
    for item in list:
        if item['id'] == item_id:
            return jsonify(item)
    return Response('Item not found', status=404)

@app.route('/getpost/<int:item_id>/<name>')
def get_post(item_id, name):
    # Append a new item to the list
    list.append({'id': item_id, 'name': name, 'done': False})
    # Return the updated list as JSON
    return jsonify(list)

@app.route('/postjson', methods=['POST'])
def post_json():
    # Get the data from the request
    data = request.get_json()
    # Auto-increment the id
    data['id'] = len(list) + 1
    # Default the name to an empty string
    data['name'] = ''
    # Default the "done" field to false
    data['done'] = False
    # Append the new item to the list
    list.append(data)
    # Return the updated list as JSON
    return jsonify(list)

# Run the web service
if __name__ == '__main__':
    app.run(host='0.0.0.0')

